<?php
session_start(); require '../config/db.php';
if (!isset($_SESSION['user_id']) || $_SESSION['role'] !== 'admin') { header('Location: ../auth/login.php'); exit(); }
if (isset($_GET['action'], $_GET['service_id']) && in_array($_GET['action'], ['approve', 'reject'], true)) {
    $serviceId = (int) $_GET['service_id']; $status = $_GET['action'] === 'approve' ? 'approved' : 'rejected';
    $service = $conn->prepare("SELECT provider_id, title FROM services WHERE service_id = ? AND status = 'pending'"); $service->bind_param('i', $serviceId); $service->execute(); $item = $service->get_result()->fetch_assoc();
    if ($item) { $update = $conn->prepare("UPDATE services SET status = ? WHERE service_id = ? AND status = 'pending'"); $update->bind_param('si', $status, $serviceId); $update->execute(); if ($update->affected_rows === 1) { $message = 'Your service "' . $item['title'] . '" has been ' . $status . '.'; $notice = $conn->prepare('INSERT INTO notifications (user_id, message) VALUES (?, ?)'); $notice->bind_param('is', $item['provider_id'], $message); $notice->execute(); } }
    header('Location: pending_approvals.php?message=' . $status); exit();
}
$sql = "SELECT s.service_id,s.title,s.description,s.created_at,c.category_name,u.full_name,u.phone_number FROM services s JOIN categories c ON c.category_id=s.category_id JOIN users u ON u.user_id=s.provider_id WHERE s.status='pending' ORDER BY s.created_at ASC";
$services = $conn->query($sql);
?>
<!doctype html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pending Approvals</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="app-shell"><div class="app-sidebar-overlay" id="sidebar-overlay"></div><div class="app-sidebar"><button type="button" class="app-sidebar-close-btn" aria-label="Close navigation menu">&times;</button><div class="brand"><div class="split-login-mark" style="width:28px;height:28px;font-size:12px">S</div>SSMS</div><a href="dashboard.php">Dashboard</a><a href="manage_users.php">Manage Users</a><a href="manage_listings.php">Manage Listings</a><a href="pending_approvals.php" class="active">Pending Approvals</a><a href="manage_categories.php">Manage Categories</a><a href="notifications.php">Notifications</a><div class="logout-link"><a href="../auth/logout.php">Logout</a></div></div><div class="app-main"><div class="app-topbar"><div class="d-flex align-items-center gap-3"><button type="button" id="hamburger-btn" class="app-hamburger-btn" aria-label="Open navigation menu"><span class="hamburger-icon"><span></span><span></span><span></span></span></button><span class="fw-semibold">Pending Approvals</span></div><div class="app-topbar-actions"><a href="notifications.php" class="app-topbar-action-btn" aria-label="Notifications">◌</a><button type="button" class="app-profile-btn" aria-label="Profile for <?php echo htmlspecialchars($_SESSION['full_name']); ?>"><?php echo htmlspecialchars(strtoupper(substr($_SESSION['full_name'], 0, 1))); ?></button><button type="button" id="theme-toggle" class="app-topbar-icon-btn" aria-label="Switch to dark mode">🌙</button></div></div><main class="app-content"><div class="admin-toolbar"><div><h1>Pending Service Approvals</h1><p>Review new service submissions before they are visible to students.</p></div></div><?php if(isset($_GET['message'])):?><div class="alert alert-success">Service <?php echo htmlspecialchars($_GET['message']); ?> and the provider has been notified.</div><?php endif;?><?php if($services->num_rows===0):?><div class="listing-empty"><span class="listing-empty-icon">✓</span><p>There are no services waiting for approval.</p></div><?php else:?><div class="listing-grid"><?php while($service=$services->fetch_assoc()):?><article class="listing-card"><div class="listing-card-header"><span class="listing-badge listing-badge-category"><?php echo htmlspecialchars($service['category_name']);?></span><span class="listing-badge listing-badge-pending">Pending</span></div><h2 class="listing-title"><?php echo htmlspecialchars($service['title']);?></h2><p class="listing-description"><?php echo htmlspecialchars($service['description']);?></p><div class="listing-meta"><div class="listing-meta-item"><span>Provider: <?php echo htmlspecialchars($service['full_name']);?></span></div><div class="listing-meta-item"><span><?php echo htmlspecialchars($service['phone_number']);?></span></div></div><div class="listing-actions"><a class="listing-action-btn" href="pending_approvals.php?action=approve&amp;service_id=<?php echo $service['service_id'];?>">Approve</a><a class="listing-action-btn listing-action-btn-danger" href="pending_approvals.php?action=reject&amp;service_id=<?php echo $service['service_id'];?>">Reject</a></div></article><?php endwhile;?></div><?php endif;?></main></div></div><script src="../assets/js/script.js"></script></body></html>
